 async function loadAsr(){if(asrRef.current)return asrRef.current;setAsrModelLoading(true);setVoiceStatus('正在加载本地语音识别模型…首次使用需要下载模型文件');try{const {pipeline}=await import('@huggingface/transformers');const device=(navigator as any).gpu?'webgpu':'wasm';asrRef.current=await pipeline('automatic-speech-recognition','onnx-community/whisper-tiny',{dtype:'q8',device});return asrRef.current}finally{setAsrModelLoading(false)}}
