 async function transcribeBlob(blob:Blob){setVoiceTranscribing(true);setVoiceStatus('正在识别你的语音…');try{const ctx=new AudioContext();const decoded=await ctx.decodeAudioData(await blob.arrayBuffer());const length=Math.ceil(decoded.duration*16000);const offline=new OfflineAudioContext(1,length,16000);const source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();const resampled=await offline.startRendering();const audio=resampled.getChannelData(0);await ctx.close();const asr=await loadAsr();const result=await asr(audio,{language:'chinese',task:'transcribe'});const transcript=String(result?.text||'').trim();if(!transcript)throw new Error('没有识别到清晰语音，请靠近麦克风再试一次。');setVoiceStatus('识别完成，正在发送…');setInput(transcript);await send(transcript)}catch(e){setVoiceStatus(e instanceof Error?e.message:'语音识别失败');showToast(e instanceof Error?e.message:'语音识别失败')}finally{setVoiceTranscribing(false)}}
 async function toggleRecording(){if(voiceRecording){recorderRef.current?.stop();setVoiceRecording(false);setVoiceStatus('正在处理录音…');return}try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('当前浏览器无法访问麦克风，请使用 HTTPS 的新版 Chrome 或 Edge。');const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});streamRef.current=stream;audioChunksRef.current=[];const mime=MediaRecorder.isTypeSupported('audio/webm;codecs=opus')?'audio/webm;codecs=opus':'audio/webm';const recorder=new MediaRecorder(stream,{mimeType:mime});recorderRef.current=recorder;recorder.ondataavailable=e=>{if(e.data.size)audioChunksRef.current.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());streamRef.current=null;const blob=new Blob(audioChunksRef.current,{type:recorder.mimeType||'audio/webm'});if(blob.size>0)void transcribeBlob(blob);else setVoiceStatus('没有录到声音，请重试。')};recorder.start(250);setVoiceRecording(true);setVoiceSeconds(0);setVoiceStatus('正在聆听，完成后再次点击结束录音。')}catch(e){setVoiceStatus(e instanceof Error?e.message:'无法启动麦克风');showToast(e instanceof Error?e.message:'无法启动麦克风')}}
 async function speakText(text:string){try{setVoiceStatus('正在生成自然语音…');const tts=await loadTts();const voice=voiceGender==='female'?'zf_001':'zm_009';const audio=await tts.generate(text.slice(0,3500),{voice,speed:1});const samples=audio.audio as Float32Array;const sampleRate=Number(audio.sampling_rate||24000);const ctx=audioContextRef.current||new AudioContext();audioContextRef.current=ctx;await ctx.resume();const buffer=ctx.createBuffer(1,samples.length,sampleRate);buffer.getChannelData(0).set(Array.from(samples));const source=ctx.createBufferSource();source.buffer=buffer;source.connect(ctx.destination);setSpeaking(true);setVoiceStatus('MyAgent 正在回应');source.onended=()=>{setSpeaking(false);setVoiceStatus('回复结束，可以继续说话')};source.start()}catch(e){setSpeaking(false);setVoiceStatus(e instanceof Error?e.message:'语音播放失败');showToast('本地语音生成失败：'+(e instanceof Error?e.message:'未知错误'))}}
