 useEffect(()=>{const onKey=(event:KeyboardEvent)=>{const mod=event.ctrlKey||event.metaKey;if(mod&&event.key.toLowerCase()==='n'){event.preventDefault();void newChat()}if(mod&&event.key.toLowerCase()==='b'){event.preventDefault();setLeft(v=>!v)}if(mod&&event.key.toLowerCase()==='j'){event.preventDefault();setRightOpen(v=>!v)}if(mod&&event.key==='Enter'){event.preventDefault();if(busy)abortControllerRef.current?.abort();else void send()}if(event.key==='Escape'){if(busy)abortControllerRef.current?.abort();setModal(null);if(voiceMode)closeVoice()}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[voiceMode,chat,activeWorkspaceId,busy,input])
